/* Offline design prototype. All records are synthetic; actions change this page's memory only. */
'use strict';
(() => {
  const D = window.AITP_DATA;
  if (!D) { document.getElementById('workbench').textContent = 'The bundled fixture data could not be loaded.'; return; }
  const $ = (s, root = document) => root.querySelector(s);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
  const icon = (name, extra = '') => `<svg class="i ${extra}" viewBox="0 0 24 24" aria-hidden="true">${D.icons[name] || D.icons['file']}</svg>`;
  const uri = (kind, id = '') => `${kind}|${id}`;
  const route = value => { const n = value.indexOf('|'); return { kind:value.slice(0,n), id:value.slice(n+1) }; };
  const shortProjects = { spectra:'Spectra research', dynamics:'Matched dynamics', anomaly:'Anomaly matching', learning:'Toy response', 'deferred-idea':'A second tie-break rule', 'dormant-method':'Dormant method', 'knowledge:toy-algebra':'Toy algebra' };
  const activityItems = [ ['home','house','Home'], ['explorer','folder-tree','Explorer'], ['library','library-big','Library'], ['knowledge','brain','Knowledge'], ['notes','notebook-pen','Notes'], ['code','code-xml','Code & Git'], ['conversations','messages-square','Conversations'] ];
  const kindIcons = { home:'house', project:'folder-tree', thread:'circle-dot', ideas:'lightbulb', library:'library-big', paper:'book-open', knowledge:'brain', entry:'brain', notes:'notebook-pen', note:'file-text', code:'code-xml', file:'file-code', conversations:'messages-square', conversation:'messages-square', settings:'settings' };
  const labelStates = { active:'In progress', 'waiting-researcher':'Needs your input', 'waiting-input':'Waiting for input', 'waiting-analysis':'Ready for analysis', 'needs-you':'Needs your input', proposed:'Proposed', paused:'Paused', dormant:'Dormant', deferred:'Deferred', stopped:'Stopped', pointer:'Linked branch', unknown:'Unclassified', done:'Archived', ready:'Ready', working:'In progress' };
  const conversations = D.illustrative.conversations.map(c => ({ ...c, localMessages:[] }));
  let initial = uri('project','spectra');
  try { if (location.hash.startsWith('#/')) initial = decodeURIComponent(location.hash.slice(2)); } catch {}
  const state = { activity:'explorer', project:'spectra', groups:[{tabs:[initial], active:initial}], focused:0, panel:false, inspector:false, sidebar:true, theme:'light', projectSection:'threads', codeSection:'changes', noteSection:'preview', sideQuery:'', history:[initial], cursor:0, modal:null, modalOrigin:null, modalSelection:null, paperPage:1, paletteIndex:0, paletteQuery:'', reviewed:new Set(), scrolls:new Map(), drafts:new Map() };
  const getProject = id => D.projects.find(p => p.id === id);
  const projectLabel = id => shortProjects[id] || getProject(id)?.title || 'Global collection';
  const active = () => state.groups[state.focused]?.active;
  const threadsFor = id => D.threads.filter(t => t.project === id && t.name && t.state !== 'pointer');
  const threadBy = id => D.threads.find(t => t.id === id);
  const conversationBy = id => conversations.find(c => c.id === id);
  function object(value) {
    const r = route(value || uri('home'));
    const item = r.kind === 'project' ? getProject(r.id) : r.kind === 'thread' ? threadBy(r.id) : r.kind === 'note' ? D.notes[r.id] : r.kind === 'conversation' ? conversationBy(r.id) : r.kind === 'paper' ? D.papers.find(p => p.id === r.id) : r.kind === 'entry' ? D.knowledge.find(k => k.id === r.id) : null;
    const project = item?.project || (r.kind === 'project' || r.kind === 'ideas' ? r.id : r.kind === 'file' || r.kind === 'code' ? D.checkouts[0]?.project : null);
    let title = item?.title || item?.name;
    if (r.kind === 'project') title = projectLabel(r.id);
    if (r.kind === 'paper') title = 'An example paper';
    if (r.kind === 'file') title = r.id.split('/').pop();
    if (!title) title = ({ home:'Your work', library:'Library', knowledge:'Knowledge', notes:'Research notes', code:'libdemo', conversations:'Conversations', ideas:'Ideas & decisions', settings:'Appearance' })[r.kind] || 'Resource unavailable';
    return {...r, item, project, title, icon:kindIcons[r.kind] || 'file'};
  }
  const navButton = (value, text, glyph, extra='') => `<button class="nav-row ${active() === value ? 'selected' : ''}" data-open="${esc(value)}" ${extra}>${icon(glyph)}<span class="label">${esc(text)}</span></button>`;
  const openButton = (value, text, css='btn', glyph='arrow-up-right') => `<button class="${css}" data-open="${esc(value)}">${icon(glyph)}${esc(text)}</button>`;
  const iconButton = (action, glyph, title, extra='') => `<button type="button" class="icon-btn" data-action="${action}" title="${esc(title)}" aria-label="${esc(title)}" ${extra}>${icon(glyph)}</button>`;
  const workButton = value => `<button class="btn primary" data-work="${esc(value)}">${icon('sparkles')}Work on this</button>`;
  const pill = status => `<span class="pill ${esc(status)}">${esc(labelStates[status] || status)}</span>`;
  const synthetic = '<span class="fixture-note">Synthetic fixture · labels and illustrative excerpts</span>';
  const empty = (title, description, action='') => `<div class="empty-state"><div class="empty-symbol">${icon('inbox')}</div><h2>${esc(title)}</h2><p>${esc(description)}</p>${action}</div>`;
  const sectionTitle = (title, count='', right='') => `<div class="section-title">${esc(title)} ${count !== '' ? `<span class="count">${count}</span>` : ''}<span class="right">${right}</span></div>`;
  const breadcrumbs = (...parts) => `<div class="breadcrumbs">${icon('folder-tree')}${parts.map(p => `<span>${esc(p)}</span>`).join(icon('chevron-right'))}</div>`;
  function sourceFor(o) { return o.item?.note || o.item?.home || (['note','entry','file'].includes(o.kind) ? o.id : o.kind === 'paper' ? `knowledge/papers/${o.id}/` : o.project ? getProject(o.project)?.home : 'topics/research.md'); }
  function textFromHtml(html) { const el = document.createElement('div'); el.innerHTML = html || ''; return el.textContent.replace(/\[([^\]]+)\]\[[^\]]+\]/g,'$1').replace(/\s+/g,' ').trim(); }
  function safeThreadExcerpt(t) {
    return textFromHtml(t.html) || `${D.notes[t.note]?.title || 'Research note'} · ${t.disposition || labelStates[t.state] || 'State not classified'}`;
  }
  function threadRow(t) { return `<button class="thread-row" data-open="${esc(uri('thread',t.id))}"><span class="thread-glyph">${icon(t.state === 'waiting-researcher' ? 'circle-alert' : t.state === 'active' ? 'circle-dot' : 'circle-dashed')}</span><span class="grow"><span class="thread-title">${esc(t.name)}</span><span class="thread-sub">${esc(safeThreadExcerpt(t))}</span><span class="thread-meta">${pill(t.state)}<span>${esc(t.date === 'unrecorded' ? 'Date unrecorded' : t.date)}</span></span></span>${icon('arrow-up-right','arrow')}</button>`; }
  function resourceRow(value,title,detail,glyph='file-text',badge='') { return `<button class="resource-row" data-open="${esc(value)}"><span class="resource-icon">${icon(glyph)}</span><span class="grow"><b>${esc(title)}</b><small>${esc(detail)}</small></span>${badge}${icon('chevron-right','sm')}</button>`; }
  function conversationRows(list) { return list.length ? `<div class="resource-list">${list.map(c => resourceRow(uri('conversation',c.id), c.id === 'c-trace' ? 'Reading discussion · Toy algebra' : c.title, `${projectLabel(c.project)} · ${c.kind} · simulated conversation`, 'messages-square',pill(c.state))).join('')}</div>` : empty('No conversations here yet','Start from this project or one of its threads to keep the task attached to its context.',workButton(active())); }
  function renderSidebar() {
    const current = state.activity;
    const label = activityItems.find(a => a[0] === current)?.[2] || 'Explorer';
    const q = state.sideQuery.toLowerCase();
    const match = text => String(text).toLowerCase().includes(q);
    let body='';
    if (current === 'explorer' || current === 'home') {
      body = `<div class="workspace-switch"><span class="workspace-symbol">a</span><span><b>Research workspace</b><small>Local · synthetic collection</small></span></div><div class="side-label">Projects <span>${D.projects.length}</span></div>`;
      const ordered = ['spectra','dynamics','anomaly','learning','knowledge:toy-algebra','deferred-idea','dormant-method'];
      body += ordered.filter(id => match(projectLabel(id))).map(id => `<button class="nav-row ${id===state.project?'selected':''}" data-project="${esc(id)}">${icon(id===state.project?'chevron-down':'chevron-right')}<span class="label">${esc(projectLabel(id))}</span></button>${id === state.project ? `<div class="nav-subtree">${navButton(uri('project',id),'Overview','layers')}${threadsFor(id).filter(t=>['active','waiting-researcher'].includes(t.state)).slice(0,4).map(t=>navButton(uri('thread',t.id),t.name,'circle-dot')).join('')}${navButton(uri('ideas',id),'Ideas & decisions','lightbulb')}${navButton(uri('note',getProject(id).home),'Project note','file-text')}</div>` : ''}`).join('');
      body += `<div class="side-group"><div class="side-label">Shared resources</div>${navButton(uri('library'),'Paper library','library-big')}${navButton(uri('knowledge'),'Knowledge collection','brain')}</div>`;
    } else if (current === 'library') {
      body = `${navButton(uri('library'),'All papers','library-big')}<div class="side-group"><div class="side-label">Reading collection</div>${D.papers.filter(p=>match('An example paper '+p.id)).map(p=>navButton(uri('paper',p.id),'An example paper','book-open')).join('')}</div><div class="notice">${icon('book-open')}<span>One fixture paper. Its PDF is unavailable in this sample.</span></div>`;
    } else if (current === 'knowledge') {
      body = `${navButton(uri('knowledge'),'Knowledge overview','brain')}<div class="side-group"><div class="side-label">Toy algebra</div>${D.knowledge.filter(k=>match(k.title)).map(k=>navButton(uri('entry',k.id),k.title,k.kind==='question'?'circle-question-mark':'sigma')).join('')}</div>`;
    } else if (current === 'notes') {
      body = `<div class="side-label">By project</div>${D.projects.filter(p=>p.notes.some(n=>match(D.notes[n]?.title || n))).map(p=>`<div class="side-group"><div class="side-label">${esc(projectLabel(p.id))}</div>${p.notes.filter(n=>match(D.notes[n]?.title || n)).map(n=>navButton(uri('note',n),D.notes[n]?.title || n,'file-text')).join('')}</div>`).join('')}`;
    } else if (current === 'code') {
      const co = D.checkouts[0];
      body = `${navButton(uri('code'),'libdemo','git-branch')}<div class="side-group"><div class="side-label">Files · synthetic checkout</div>${Object.keys(co.samples).filter(f=>match(f)).map(f=>navButton(uri('file',f),f,f.endsWith('.md')?'file-text':'file-code')).join('')}</div>`;
    } else if (current === 'conversations') {
      body = `${navButton(uri('conversations'),'All conversations','messages-square')}${['working','needs-you','ready','done'].map(status=>{ const list=conversations.filter(c=>c.state===status && match(c.title)); return list.length ? `<div class="side-group"><div class="side-label">${esc(labelStates[status])}</div>${list.map(c=>navButton(uri('conversation',c.id),c.id==='c-trace'?'Reading discussion · Toy algebra':c.title,'message-square-plus')).join('')}</div>`:''; }).join('')}`;
    }
    if (q && !body.includes('data-open') && !body.includes('data-project')) body += '<p class="fixture-note">No matching resources. Try a shorter phrase.</p>';
    return `<div class="side-head">${esc(label)}${iconButton('palette','search','Find a resource')}</div><div class="side-body">${current !== 'home' && current !== 'explorer' ? `<input class="side-search" aria-label="Filter ${esc(label)}" placeholder="Filter ${esc(label.toLowerCase())}…" value="${esc(state.sideQuery)}">`:''}${body}</div><div class="sidebar-foot">${icon('shield-check')}Local demonstration · writes off</div>`;
  }
  function projectFrontier(p) {
    if (p.id === 'knowledge:toy-algebra') return `<div class="notice">${icon('book-open')}<span>This is a synthetic learning story, not a research result. The source's mathematical body is withheld from this design preview.</span></div>`;
    const owners = p.id === 'spectra' ? ['topics/spectra/selfconsistent/research.md','topics/spectra/continuation/research.md'] : [p.home];
    return `<section class="frontier-summary" aria-label="Current understanding">${sectionTitle('Current understanding', '', 'Synthetic source excerpts')}${owners.map(path => {
      const note = D.notes[path];
      const opening = note?.opening || p.homeHtml || '';
      return `<div class="frontier-passage"><button class="source-link" data-open="${esc(uri('note',path))}">${icon('file-text')}${esc(note?.title || p.title)}${icon('arrow-up-right')}</button><p>${esc(textFromHtml(opening))}</p></div>`;
    }).join('')}</section>`;
  }
  function projectPage(id) {
    const p=getProject(id); if(!p) return unavailable();
    const threads=threadsFor(id), attention=threads.filter(t=>t.state==='waiting-researcher'), inProgress=threads.filter(t=>['active','waiting-analysis','waiting-input'].includes(t.state)), parked=threads.filter(t=>!attention.includes(t)&&!inProgress.includes(t));
    const conv=conversations.filter(c=>c.project===id);
    return `<div class="document">${breadcrumbs('Projects',projectLabel(id))}<div class="hero"><div><div class="eyebrow">Research project <span>·</span> synthetic</div><h1>${esc(projectLabel(id))}</h1><p class="hero-description">${esc(p.question)}</p></div></div><div class="hero-actions">${workButton(uri('project',id))}${openButton(uri('note',p.home),'Open project note','btn','file-text')}</div>${projectFrontier(p)}<div class="object-stats"><div class="object-stat"><b>${threads.length}</b>research threads</div><div class="object-stat"><b>${attention.length}</b>awaiting your input</div><div class="object-stat"><b>${conv.length}</b>conversations</div></div><div class="subnav"><button data-project-section="threads" class="${state.projectSection==='threads'?'on':''}">Threads</button><button data-project-section="conversations" class="${state.projectSection==='conversations'?'on':''}">Conversations</button><button data-project-section="activity" class="${state.projectSection==='activity'?'on':''}">Activity</button></div>${state.projectSection==='threads' ? `${attention.length?`${sectionTitle('Needs your input',attention.length)}${attention.map(threadRow).join('')}`:''}${inProgress.length?`${sectionTitle('In progress',inProgress.length,'From Current work')}${inProgress.map(threadRow).join('')}`:''}${parked.length?`<details class="parked" ${!attention.length&&!inProgress.length?'open':''}><summary>Other threads · ${parked.length} paused, proposed or unclassified</summary>${parked.map(threadRow).join('')}</details>`:''}${!threads.length?empty('No threads yet','This fixture has no extracted threads. Open the source note to inspect its structure.'):''}` : state.projectSection==='conversations' ? conversationRows(conv) : activityList(id)}<p class="fixture-note" style="margin-top:23px">Projected from synthetic research notes. Thread labels are fixture state, not validated research results.</p></div>`;
  }
  function threadPage(id) {
    const t=threadBy(id); if(!t)return unavailable();
    const c=conversations.filter(c=>c.origin?.id===id);
    return `<div class="document">${breadcrumbs(projectLabel(t.project),D.notes[t.note]?.title || 'Research note','Thread')}<div class="eyebrow">Research thread · synthetic</div><h1>${esc(t.name)}</h1><div class="hero-actions">${pill(t.state)}<span class="fixture-note">Updated ${esc(t.date)}</span></div><div class="source-box"><div class="eyebrow">Current work · illustrative excerpt</div><p class="quote-text">${esc(safeThreadExcerpt(t))}</p>${openButton(uri('note',t.note),`research.md · lines ${t.lines.join('–')}`,'source-link','file-text')}</div><div class="hero-actions">${workButton(uri('thread',id))}${openButton(uri('note',t.note),'Read source note','btn','book-open')}</div>${sectionTitle('Conversations',c.length)}${conversationRows(c)}${sectionTitle('Where this thread lives')}<div class="resource-list">${resourceRow(uri('project',t.project),projectLabel(t.project),'Parent project · research context','folder-tree')}${resourceRow(uri('note',t.note),D.notes[t.note]?.title,t.note,'file-text')}</div><p class="fixture-note" style="margin-top:20px">This page demonstrates ownership and context. The fixture passage does not establish a scientific result.</p></div>`;
  }
  function homePage() { return `<div class="document">${breadcrumbs('Workspace','Home')}<div class="eyebrow">Research workspace · sample day</div><h1>Pick up where you left off.</h1><p class="hero-description">Your projects, open questions and conversations, in one place.</p>${sectionTitle('Waiting for you',conversations.filter(c=>c.state==='needs-you').length)}${conversationRows(conversations.filter(c=>c.state==='needs-you'))}${sectionTitle('Projects',D.projects.length)}<div class="resource-list">${['spectra','dynamics','anomaly','learning'].map(id=>resourceRow(uri('project',id),projectLabel(id),getProject(id).question,'folder-tree')).join('')}</div><p class="fixture-note" style="margin-top:20px">All activity, states and timestamps in this view are synthetic.</p></div>`; }
  function ideasPage(id) { const decisions=D.decisions.filter(d=>d.note.includes(`/${id}/`) || d.note==='topics/research.md'); return `<div class="document">${breadcrumbs(projectLabel(id),'Ideas & decisions')}<div class="eyebrow">Research context · synthetic</div><h1>Ideas & decisions</h1><p class="hero-description">Keep possible directions distinct from choices already recorded.</p>${sectionTitle('Seeds',D.ideas.length)}${D.ideas.map(i=>`<div class="source-box"><div class="eyebrow">${icon('lightbulb')}Shared programme seed</div><p class="quote-text">${esc(i.text)}</p>${openButton(uri('note',i.note),'Open source','source-link','file-text')}</div>`).join('')}${sectionTitle('Recorded choices',decisions.length)}${decisions.map(d=>`<div class="notice">${icon('scale')}<span>${esc(d.text)}<br><span class="fixture-note">Illustrative recorded choice · ${esc(d.source)}</span></span></div>`).join('')}</div>`; }
  function libraryPage() { return `<div class="document">${breadcrumbs('Shared resources','Library')}<div class="eyebrow">Source collection</div><h1>Your paper library</h1><p class="hero-description">Source material, reading progress and the questions that lead back to it.</p><div class="subnav"><button class="on">All papers · 1</button></div><div class="resource-list">${D.papers.map(p=>resourceRow(uri('paper',p.id),'An example paper',`Fixture identifier ${p.id} · ${p.version} · partial close reading`,'book-open',pill('awaiting review'))).join('')}</div><div class="notice">${icon('eye')}<span>Metadata demonstration. Identifiers in this synthetic collection are not verified citations.</span></div></div>`; }
  function paperPage(id) {
    const p=D.papers.find(p=>p.id===id);if(!p)return unavailable();
    const second=state.paperPage===2;
    return `<div class="document paper-document">${breadcrumbs('Library','An example paper')}<div class="eyebrow">Static paper illustration · not a PDF</div><h1>An example paper</h1><p class="fixture-note">Fixture identifier ${esc(p.id)} · edition ${esc(p.version)} · actual PDF unavailable</p><div class="reader-controls"><div class="page-switch">${iconButton('paper-prev','chevron-left','Previous illustrative page',!second?'disabled':'')}<span>Page ${state.paperPage} of 2</span>${iconButton('paper-next','chevron-right','Next illustrative page',second?'disabled':'')}</div><span class="pill">${esc(p.version)} · static UI fixture</span><button class="btn" data-selection-text="${esc(uri('paper',id))}">${icon('quote')}Ask about selection</button></div><article class="paper-sheet selectable-source" data-source-kind="paper" data-source-id="${esc(id)}" data-source-page="${state.paperPage}"><div class="paper-running">AITP · synthetic reading example <span>Edition ${esc(p.version)}</span></div>${second?`<h2>2. What the criterion leaves open</h2><p>Suppose an iteration gives a small residual for the chosen map. That statement concerns a fixed discretization.</p><div class="paper-passage" id="paper-boundary"><span class="margin-label">Passage A</span><p>A small residual measures agreement with the map at the chosen discretization. It does not establish convergence under grid refinement.</p></div><p>A continuation task can therefore keep the stopping condition and the independent refinement check visible as separate questions.</p><div class="paper-note">This passage is a deliberately simple teaching illustration written for this interface prototype. It is not extracted from a publication.</div><button class="btn" data-select-passage="paper-boundary" data-source-object="${esc(uri('paper',id))}">${icon('highlighter')}Discuss passage A</button>`:`<h2>1. A toy fixed-point iteration</h2><p>Let <i>F</i> be a map and <i>x</i> a trial value. The residual records the difference between that value and its image.</p><div class="paper-passage" id="paper-residual"><span class="margin-label">Definition 1</span><div class="math-display"><i>r</i>(<i>x</i>) = |<i>F</i>(<i>x</i>) − <i>x</i>| <span>(1)</span></div><p>The condition <i>r</i>(<i>x</i>) ≤ ε is a stopping criterion for this chosen map. It does not by itself assess the effect of changing the discretization.</p></div><p>Page 2 makes that remaining question explicit.</p><button class="btn" data-select-passage="paper-residual" data-source-object="${esc(uri('paper',id))}">${icon('highlighter')}Discuss definition 1</button>`}<footer class="paper-number">${state.paperPage}</footer></article><p class="fixture-note">Select text, or use a named passage. The draft retains the edition, page and exact selected text.</p></div>`;
  }
  function knowledgePage() { return `<div class="document">${breadcrumbs('Shared resources','Knowledge')}<div class="eyebrow">Learning collection</div><h1>Knowledge, with its sources.</h1><p class="hero-description">Explanations and open questions stay connected to where they came from.</p>${sectionTitle('Toy algebra',D.knowledge.length)}<div class="resource-list">${D.knowledge.map(k=>resourceRow(uri('entry',k.id),k.title,`${k.kind==='atom'?'Concept':'Open question'} · ${k.support} · review awaiting`,k.kind==='atom'?'sigma':'circle-question-mark')).join('')}</div><div class="notice">${icon('eye')}<span>Only metadata is shown. Synthetic mathematical claims are not presented as verified learning material.</span></div></div>`; }
  function entryPage(id) { const k=D.knowledge.find(k=>k.id===id);if(!k)return unavailable();return `<div class="document">${breadcrumbs('Knowledge','Toy algebra')}<div class="eyebrow">${k.kind==='atom'?'Concept':'Open question'} · synthetic metadata</div><h1>${esc(k.title)}</h1><div class="hero-actions">${pill('Awaiting review')}${workButton(uri('entry',id))}</div><div class="source-box"><div class="eyebrow">Source and review boundary</div><p class="quote-text">This entry demonstrates a ${k.kind==='atom'?'concept linked to a source':'question retained for further study'}. Its mathematical body is intentionally omitted from this design preview.</p><span class="fixture-note">Support label in fixture: ${esc(k.support)} · review: ${esc(k.review)}</span></div>${sectionTitle('Source collection')}<div class="resource-list">${resourceRow(uri('paper',D.papers[0].id),'An example paper','Synthetic source locator · not a verified citation','book-open')}</div>${sectionTitle('Learning conversation')}<div class="resource-list">${resourceRow(uri('conversation','c-trace'),'Reading discussion · Toy algebra','Transcript body withheld · mathematical claim unverified','messages-square')}</div></div>`; }
  function notesPage() { return `<div class="document">${breadcrumbs('Shared resources','Notes')}<div class="eyebrow">Research record</div><h1>Research notes</h1><p class="hero-description">The source record behind projects and threads. Browse it independently of a conversation.</p><div class="resource-list">${Object.values(D.notes).filter(n=>n.kind!=='root').map(n=>resourceRow(uri('note',n.id),n.title,`${projectLabel(n.project)} · ${n.lines} lines`,'file-text')).join('')}</div></div>`; }
  function notePage(id) {
    const mapProject=D.projects.find(p=>p.home===id&&p.homeHtml);const n=D.notes[id] || (mapProject?{id,title:mapProject.title,project:mapProject.id,opening:mapProject.homeHtml,question:mapProject.question}:null); if(!n) return `<div class="document">${breadcrumbs('Notes','Source reference')}<h1>Referenced source</h1><div class="source-box"><p class="inspect-path">${esc(id)}</p></div>${empty('Source text is not bundled','This sample retains the locator, but it cannot open the referenced passage.',openButton(uri('notes'),'Browse available notes','btn','notebook-pen'))}</div>`;
    const ts=D.threads.filter(t=>t.note===id&&t.name);const safe=n.project==='knowledge:toy-algebra';
    const previewText=safe?'This synthetic learning note is represented by its title, source path and thread labels. The mathematical body is withheld.':textFromHtml(n.opening) || n.question || 'Programme map from the synthetic fixture.';
    return `<div class="document">${breadcrumbs(projectLabel(n.project),'Notes')}<div class="eyebrow">Source note · read-only preview</div><h1>${esc(n.title)}</h1><p class="inspect-path">${esc(id)}</p><div class="hero-actions" style="margin-top:16px">${workButton(uri('note',id))}${n.project?openButton(uri('project',n.project),'Open project','btn','folder-tree'):''}</div><div class="subnav"><button data-note-section="preview" class="${state.noteSection==='preview'?'on':''}">Preview</button><button data-note-section="source" class="${state.noteSection==='source'?'on':''}">Excerpt</button><button data-note-section="history" class="${state.noteSection==='history'?'on':''}">History</button></div>${state.noteSection==='history'?empty('No note revisions bundled','The sample provides a current snapshot. Git history is available for the illustrative libdemo checkout.',openButton(uri('code'),'Open Code & Git','btn','git-branch')):state.noteSection==='source'?`<p class="fixture-note">Reconstructed display excerpt · not the complete source file</p>${codeBlock(`# ${n.title}\n\n${previewText}\n\n## Current work\n\n${ts.map(t=>`- ${t.name} — ${t.state}`).join('\n')}`)}`:`<div class="source-box"><div class="eyebrow">Opening question · synthetic</div><p class="quote-text">${esc(previewText)}</p></div>${id==='topics/spectra/selfconsistent/research.md'?residualNote(id):''}${sectionTitle('Current work',ts.length)}${ts.length?ts.map(threadRow).join(''):empty('No structured threads','This note has no extracted Current work entries in the fixture.')}`}<p class="fixture-note" style="margin-top:21px">Illustrative display excerpt. Use source provenance to distinguish recorded text from interpretation.</p></div>`;
  }
  function residualNote(id) {
    return `<section class="source-box selectable-source" data-source-kind="note" data-source-id="${esc(id)}"><div class="eyebrow">Synthetic teaching passage · added for this UI demonstration</div><div id="note-residual"><div class="math-display"><i>r</i>(<i>x</i>) = |<i>F</i>(<i>x</i>) − <i>x</i>|</div><p class="quote-text">A small residual measures agreement with the chosen map. It does not by itself establish precision under grid refinement.</p></div><div class="hero-actions"><button class="btn" data-select-passage="note-residual" data-source-object="${esc(uri('note',id))}">${icon('highlighter')}Work on this passage</button>${openButton(uri('paper',D.papers[0].id),'Open paper illustration','btn','book-open')}</div><span class="fixture-note">This explanatory block is authored for the prototype, separate from the bundled research note.</span></section>`;
  }
  function codeBlock(text, diff=false) { return `<div class="code-block">${String(text).split('\n').map((line,i)=>`<div class="code-line ${diff&&line.startsWith('+')?'add':diff&&line.startsWith('-')?'del':''}"><span class="line-number">${i+1}</span><span class="code-content">${esc(line)}</span></div>`).join('')}</div>`; }
  function codePage() {
    const co=D.checkouts[0];const changes=D.illustrative.workingTree[co.id]||[],commits=D.illustrative.commits[co.id]||[];
    return `<div class="document">${breadcrumbs('Code & Git','libdemo')}<div class="eyebrow">Development checkout · simulated</div><h1>libdemo</h1><p class="hero-description">A shared checkout connected to Spectra research.</p><div class="notice">${icon('git-branch')}<span>Read-only fixture. Branch not supplied; commits and changes below are illustrative.</span></div><div class="subnav code-tabs">${['files','changes','history'].map(s=>`<button data-code-section="${s}" class="${state.codeSection===s?'on':''}">${s[0].toUpperCase()+s.slice(1)}${s==='changes'?' · 1':''}</button>`).join('')}</div>${state.codeSection==='files'?`<div class="resource-list">${Object.keys(co.samples).map(f=>resourceRow(uri('file',f),f,'Bundled synthetic source','file-code')).join('')}</div>`:state.codeSection==='history'?`<div class="resource-list">${commits.map(c=>`<div class="resource-row">${icon('git-commit-horizontal')}<span class="grow"><b>${esc(c.message)}</b><small>${esc(c.date.slice(0,10))} · illustrative commit</small></span><span class="mono">${esc(c.sha)}</span></div>`).join('')}</div>`:changes.map(c=>`<div class="section-title">${icon('file-code')}${esc(c.file)}<span class="right">Modified · illustrative diff</span></div>${codeBlock(c.diff,true)}<div class="hero-actions">${openButton(uri('file',c.file),'Open fixture source','btn','file-code')}${openButton(uri('conversation','c-schedules'),'Related conversation','btn','messages-square')}</div>`).join('')}<p class="fixture-note" style="margin-top:20px">The proposed diff and source snapshot are independent UI fixtures. No repository operation runs from this view.</p></div>`;
  }
  function filePage(id) { const text=D.checkouts[0].samples[id];return `<div class="document">${breadcrumbs('Code & Git','libdemo',id.split('/').pop())}<div class="eyebrow">Source file · synthetic snapshot</div><h1>${esc(id.split('/').pop())}</h1><p class="inspect-path">${esc(id)}</p>${text?codeBlock(text):empty('File contents unavailable','This file is listed by the fixture but its body is not bundled.')}<div class="hero-actions">${workButton(uri('file',id))}${openButton(uri('code'),'Checkout overview','btn','git-branch')}</div></div>`; }
  function activityList(project=null) { const list=D.illustrative.activity.filter(a=>!project||a.project===project);return list.length?list.map(a=>`<div class="activity-line"><time>${esc(a.at.slice(5,10))}</time>${icon(a.kind==='commit'?'git-commit-horizontal':a.kind==='run'?'flask-conical':'messages-square')}<button data-open="${esc(a.ref.startsWith('c-')?uri('conversation',a.ref):a.kind==='commit'?uri('code'):uri('note',a.ref))}">${esc(a.text)}</button></div>`).join(''):empty('No activity in this sample','This project has no bundled activity records.'); }
  function conversationsPage() { return `<div class="document">${breadcrumbs('Workspace','Conversations')}<div class="eyebrow">Context-bound sessions</div><h1>Conversations</h1><p class="hero-description">Every task keeps its origin, its sources and its outcome.</p><div class="hero-actions">${workButton(uri('project',state.project))}<span class="fixture-note">Start from ${esc(projectLabel(state.project))}</span></div>${sectionTitle('In progress')}${conversationRows(conversations.filter(c=>c.state==='working'))}${sectionTitle('Needs your input')}${conversationRows(conversations.filter(c=>c.state==='needs-you'))}${conversations.some(c=>c.state==='ready')?sectionTitle('Created in this preview')+conversationRows(conversations.filter(c=>c.state==='ready')):''}${sectionTitle('Archived examples')}${conversationRows(conversations.filter(c=>c.state==='done'))}</div>`; }
  function originRoute(c) { if(c.localOrigin)return c.localOrigin;if(c.origin.type==='thread')return uri('thread',c.origin.id);if(c.origin.type==='paper')return uri('paper',c.origin.id);return uri('project',c.project); }
  function conversationPage(id) {
    const c=conversationBy(id);if(!c)return unavailable();
    const trace=id==='c-trace';const origin=originRoute(c);const safeTask=trace?'Review the source assumptions for the open learning question.':c.task;
    const message=(role,text)=>`<div class="session-message"><div class="speaker"><span class="avatar ${role==='agent'?'agent':''}">${role==='agent'?'a':icon('user')}</span>${role==='agent'?'AITP · simulated':'Researcher'}<small>local preview</small></div><p>${esc(text)}</p></div>`;
    let transcript=c.local?message('agent','This demonstration session is attached to the selected research object. Its task and context are shown above. Type a message to try the composer; no model or tool will run.') : message('user',trace?'Review the assumptions behind this learning question.':c.messages.find(m=>m.role==='user')?.md || safeTask);
    if(!c.local) transcript += `<details class="session-tools"><summary>${c.context.length} source references · illustrative context</summary><ul>${c.context.map(x=>`<li>${esc(x.label)}</li>`).join('')}</ul></details>`;
    if(trace) transcript+=message('agent','The illustrative transcript contains an unverified mathematical claim. This preview shows its source and question labels only; it does not reproduce the argument or imply a verified theorem.');
    else if(!c.local) transcript+=message('agent',id==='c-schedules'?'The example conversation links a comparison task to a proposed note change. The run and numerical results in the original fixture are simulated. Review the proposal in its source context.':id==='c-static'?'This sample keeps a research choice open and presents it for discussion. A recorded choice would belong to the source note; this preview only demonstrates that handoff.':'This archived example links an analytic task to a note. Its outcome label is illustrative.');
    if(c.changes?.length) transcript+=`<div class="outcome-card"><div class="outcome-head">${icon('git-pull-request')}Proposed note change <span class="grow"></span>${pill(state.reviewed.has(id)?'Reviewed locally':'proposed')}</div><div class="outcome-body">${esc(c.changes[0].title)}<br><span class="fixture-note">Synthetic proposal · no file has changed</span></div><div class="outcome-foot"><button class="btn" data-preview-change="${esc(id)}">${icon('eye')}Preview proposal</button><button class="btn ghost" data-review="${esc(id)}">${state.reviewed.has(id)?'Reviewed in preview':'Mark reviewed · demo'}</button></div></div>`;
    if(id==='c-static') transcript+=`<div class="outcome-card"><div class="outcome-head">${icon('scale')}Decision remains open</div><div class="outcome-body">${esc(c.messages.find(m=>m.role==='decision')?.title || 'Review the alternatives')}<br><span class="fixture-note">Illustrative handoff · no decision recorded by this preview</span></div><div class="outcome-foot">${openButton(origin,'Inspect research thread','btn','circle-dot')}</div></div>`;
    transcript+=c.localMessages.map(m=>message(m.role,m.text)).join('');
    return `<div class="conversation"><header class="session-head"><button class="session-origin" data-open="${esc(origin)}">${icon('circle-dot')}${esc(trace?'Toy algebra · source question':c.origin.label)}${icon('arrow-up-right')}</button><h1>${esc(trace?'Reading discussion · Toy algebra':c.title)}</h1>${c.selection?`<div class="selection-chip">${icon('highlighter')}${esc(c.selection.locator)}</div>`:''}<div class="session-meta"><span class="pill active">${icon('sparkles')}${esc(c.kind)}</span><span>Simulated session</span><span>·</span><span>Writes off</span>${pill(c.state)}</div></header><div class="session-body"><div class="session-task"><div class="eyebrow">Task · ${esc(projectLabel(c.project))}</div>${esc(safeTask)}</div>${c.selection?`<details class="session-selection"><summary>Selected source passage · ${esc(c.selection.locator)}</summary><blockquote>${esc(c.selection.text)}</blockquote><p class="inspect-path">${esc(c.selection.source)}</p></details>`:''}${transcript}</div><form class="composer" data-compose="${esc(id)}"><div class="box"><textarea aria-label="Message for ${esc(trace?'reading discussion':c.title)}" placeholder="Continue this task…" rows="2">${esc(state.drafts.get(id)||'')}</textarea><div class="bar"><span class="fixture-note">${icon('link')} ${c.context.length} context references</span><span class="grow"></span><button class="btn primary" type="submit">Add message ${icon('arrow-up-right')}</button></div></div><p class="composer-hint">Local simulation only · Ctrl / ⌘ + Enter to add · resets on reload</p></form></div>`;
  }
  function settingsPage() {return `<div class="document">${breadcrumbs('Workspace','Appearance')}<div class="eyebrow">Personal workspace</div><h1>Make room for your work.</h1><p class="hero-description">Choose a reading surface. Appearance changes stay in this browser tab until reload.</p>${sectionTitle('Theme')}<div class="settings-list">${['light','dark'].map(t=>`<button class="settings-option ${state.theme===t?'selected':''}" data-theme="${t}">${icon(t==='light'?'sun':'moon')}${t==='light'?'Linen · Light':'Forest · Dark'}</button>`).join('')}</div>${sectionTitle('Workspace controls')}<div class="resource-list"><button class="resource-row" data-action="sidebar">${icon('panel-left')}<span class="grow"><b>Toggle sidebar</b><small>Keep more space for the document</small></span><kbd class="kbd">Ctrl B</kbd></button><button class="resource-row" data-action="panel">${icon('panel-bottom')}<span class="grow"><b>Toggle activity panel</b><small>Show illustrative work activity below the editor</small></span><kbd class="kbd">Ctrl J</kbd></button></div><div class="notice">${icon('shield-check')}<span>This design artifact has no model connection, credentials, API or repository write path.</span></div></div>`;}
  const unavailable = () => empty('Resource unavailable','The link does not identify a bundled fixture object.',openButton(uri('home'),'Return to workspace','btn','house'));
  function page(value) {if(!value)return empty('A little room to think.','Open a project or resource from the sidebar, or find anything with the command palette.',`<button class="btn" data-action="palette">${icon('search')}Find a resource <kbd class="kbd">Ctrl K</kbd></button>`);const {kind,id}=route(value);return ({home:homePage,project:projectPage,thread:threadPage,ideas:ideasPage,library:libraryPage,paper:paperPage,knowledge:knowledgePage,entry:entryPage,notes:notesPage,note:notePage,code:codePage,file:filePage,conversations:conversationsPage,conversation:conversationPage,settings:settingsPage}[kind]||unavailable)(id);}
  function renderInspector() {
    const o=object(active());const source=sourceFor(o);const related=conversations.filter(c=>c.origin?.id===o.id || o.kind==='project'&&c.project===o.id);
    return `<div class="inspect-head">Context${iconButton('inspector','panel-right','Hide inspector')}</div><section class="insp-sec"><div class="eyebrow">${icon(o.icon)}${esc(o.kind)}</div><h2 class="inspect-name">${esc(o.title)}</h2><dl class="kv"><div class="kv-row"><dt>Collection</dt><dd>Synthetic workspace</dd></div><div class="kv-row"><dt>Project</dt><dd>${esc(projectLabel(o.project))}</dd></div><div class="kv-row"><dt>Mode</dt><dd>Read only</dd></div></dl>${workButton(active() || uri('project',state.project))}</section><section class="insp-sec"><div class="insp-title">Source of context</div><p class="inspect-path">${esc(source || 'No source reference')}</p>${source?openButton(uri('note',source),'Inspect source','source-link','file-text'):''}<p class="fixture-note">Source labels come from bundled fixtures. Content has not been scientifically validated.</p></section><section class="insp-sec"><div class="insp-title">Related conversations <span>${related.length}</span></div>${related.length?related.map(c=>`<button class="inspect-link" data-open="${esc(uri('conversation',c.id))}">${esc(c.id==='c-trace'?'Reading discussion · Toy algebra':c.title)}<small>${esc(labelStates[c.state]||c.state)} · simulated</small></button>`).join(''):'<p class="fixture-note">No conversation attached to this object yet.</p>'}</section><section class="insp-sec"><div class="insp-title">Workspace shortcuts</div><div class="kv"><div class="kv-row"><span>Find anything</span><kbd class="kbd">Ctrl K</kbd></div><div class="kv-row"><span>Split editor</span><kbd class="kbd">Ctrl + &#92;</kbd></div><div class="kv-row"><span>Back / forward</span><kbd class="kbd">Alt ← →</kbd></div></div></section>`;
  }
  function captureScrolls() { document.querySelectorAll('.group').forEach(g=>{const group=state.groups[Number(g.dataset.group)];if(group?.active)state.scrolls.set(`${g.dataset.group}:${group.active}`,g.querySelector('.view')?.scrollTop||0);}); }
  function render() {
    const o=object(active());document.documentElement.dataset.theme=state.theme;
    document.title=`${o.title} — AITP design prototype`;
    $('#workbench').innerHTML=`<div class="workbench ${state.groups.length===2?'is-split':''} ${!state.inspector?'hide-inspector':''} ${!state.sidebar?'hide-sidebar':''}"><header class="titlebar"><div class="brand"><span class="brand-mark">a</span></div><span class="brand-name">AITP</span><div class="nav-btns">${iconButton('back','arrow-left','Go back (Alt + Left)',state.cursor===0?'disabled':'')}${iconButton('forward','arrow-right','Go forward (Alt + Right)',state.cursor>=state.history.length-1?'disabled':'')}</div><div class="title-project"><button data-open="${esc(o.project?uri('project',o.project):uri('home'))}">${esc(projectLabel(o.project))}</button><span class="slash last">/</span><span class="last">${esc(o.kind==='project'?'Overview':o.kind[0].toUpperCase()+o.kind.slice(1))}</span></div><button class="omnibox" data-action="palette" aria-label="Open command palette">${icon('search')}<span>Find a resource or command…</span><kbd class="kbd">Ctrl K</kbd></button><div class="demo-chip"><span class="tiny-dot"></span>Design preview</div><div class="title-right">${iconButton('split','columns-2','Split editor (Ctrl + Backslash)')}${iconButton('inspector','panel-right','Toggle inspector')}</div></header><nav class="activitybar" aria-label="Workspace views">${activityItems.map(([a,g,l],i)=>`${i===2?'<div class="rail-divider"></div>':''}<button class="act ${state.activity===a?'on':''}" data-activity="${a}" aria-label="${l}" title="${l}" ${state.activity===a?'aria-current="page"':''}>${icon(g)}</button>`).join('')}<span class="act-spacer"></span><button class="act" data-action="palette" aria-label="Search" title="Search (Ctrl K)">${icon('search')}</button><button class="act" data-action="theme" aria-label="Toggle theme" title="Toggle light / dark">${icon(state.theme==='light'?'moon':'sun')}</button><button class="act" data-open="${uri('settings')}" aria-label="Settings" title="Appearance">${icon('settings')}</button></nav><aside class="sidebar" aria-label="Resource explorer">${renderSidebar()}</aside><main class="main"><div class="groups">${state.groups.map((g,i)=>`<section class="group ${i===state.focused?'focused':''}" data-group="${i}" aria-label="Editor group ${i+1}"><div class="tabs" role="tablist" aria-label="Open resources in editor ${i+1}">${g.tabs.map(u=>{const t=object(u);return `<div class="tab ${u===g.active?'on':''}"><button class="tab-main" role="tab" aria-selected="${u===g.active}" data-tab="${esc(u)}" data-tab-group="${i}" title="${esc(t.title)}">${icon(t.icon)}<span>${esc(t.title)}</span></button><button class="close-tab" data-close="${esc(u)}" data-tab-group="${i}" aria-label="Close ${esc(t.title)}">${icon('x')}</button></div>`;}).join('')}<div class="tabs-tools">${iconButton(i?'unsplit':'split',i?'x':'columns-2',i?'Close split':'Split editor')}</div></div><div class="view" role="tabpanel">${page(g.active)}</div></section>`).join('')}</div>${state.panel?`<section class="panel" aria-label="Activity panel"><div class="panel-tabs"><button class="on">Activity · simulated</button><span class="grow"></span>${iconButton('panel','x','Close activity panel')}</div><div class="panel-body">${activityList(state.project)}</div></section>`:''}</main><aside class="inspector" aria-label="Context inspector">${renderInspector()}</aside><footer class="statusbar"><span class="item">${icon('folder-tree')}research-workspace</span><span class="item">${icon('shield-check')}Writes off</span><span class="right"><span class="item optional">Synthetic data · no model connected</span><button class="item" data-action="panel">${icon('panel-bottom')}Activity</button><span class="item optional">${state.theme==='light'?'Linen':'Forest'}</span></span></footer></div>`;
    document.querySelectorAll('.group').forEach(g=>{const s=state.groups[Number(g.dataset.group)];g.querySelector('.view').scrollTop=state.scrolls.get(`${g.dataset.group}:${s.active}`)||0;});
  }
  function inferActivity(value) {const o=object(value);if(o.project&&getProject(o.project))state.project=o.project;const map={project:'explorer',thread:'explorer',ideas:'explorer',note:'notes',paper:'library',entry:'knowledge',file:'code',conversation:'conversations'};if(map[o.kind])state.activity=map[o.kind];else if(activityItems.some(a=>a[0]===o.kind))state.activity=o.kind;}
  function open(value, options={}) {
    captureScrolls();if(options.group!==undefined)state.focused=options.group;
    const g=state.groups[state.focused];if(!g.tabs.includes(value))g.tabs.push(value);g.active=value;
    if(options.activity!==false)inferActivity(value);
    state.sideQuery='';
    if(options.history!==false&&state.history[state.cursor]!==value){state.history=state.history.slice(0,state.cursor+1);state.history.push(value);state.cursor++;history.pushState({aitp:state.cursor},'',`#/${encodeURIComponent(value)}`);}
    render();$('#announcements').textContent=`Opened ${object(value).title}`;
  }
  function navigate(delta) {const next=state.cursor+delta;if(next<0||next>=state.history.length)return;history.go(delta);}
  function closeTab(value, groupIndex) {captureScrolls();const g=state.groups[groupIndex],index=g.tabs.indexOf(value);g.tabs=g.tabs.filter(x=>x!==value);if(g.active===value)g.active=g.tabs[Math.max(0,index-1)]||null;state.focused=groupIndex;render();}
  function split() {captureScrolls();if(state.groups.length===2){state.focused=1-state.focused;render();return;}const value=active();state.groups.push({tabs:value?[value]:[],active:value});state.focused=1;render();toast('Split editor opened. Pick a resource for this group.');}
  function unsplit() {captureScrolls();state.groups[1]?.tabs.forEach(t=>{if(!state.groups[0].tabs.includes(t))state.groups[0].tabs.push(t);});state.groups=state.groups.slice(0,1);state.focused=0;render();}
  let returnFocus=null;
  function showModal(html,kind) {returnFocus=document.activeElement;state.modal=kind;$('#overlay').innerHTML=`<div class="scrim" data-dismiss="true">${html}</div>`;requestAnimationFrame(()=>$('#overlay input, #overlay textarea, #overlay button')?.focus());}
  function closeModal() {state.modal=null;$('#overlay').innerHTML='';if(returnFocus?.isConnected)returnFocus.focus();else $('.omnibox')?.focus();}
  function preciseSelection(source, text, block) {
    const isPaper=source.dataset.sourceKind==='paper';
    const id=source.dataset.sourceId;
    const sourcePath=isPaper ? `knowledge/papers/${id}/static-illustration` : id;
    return {text:text.trim(),source:sourcePath,locator:isPaper?`Edition v2 · page ${source.dataset.sourcePage} · ${block}`:`Prototype teaching passage · ${block}`,kind:isPaper?'paper':'note'};
  }
  function startWork(value, selection=null) {
    const o=object(value);state.modalOrigin=value;state.modalSelection=selection;
    const task=selection ? 'Explain the selected passage and propose a clear statement of its remaining verification boundary.' : o.kind==='thread'&&o.item?.next ? o.item.next : `Review the current state of ${o.title} and identify the next useful step.`;
    showModal(`<form class="sheet" id="session-form" role="dialog" aria-modal="true" aria-labelledby="session-title"><div class="sheet-head"><div class="grow"><div class="eyebrow">Context-bound conversation</div><h2 id="session-title">Work on this.</h2><p>${esc(o.title)} · ${esc(projectLabel(o.project))}</p></div>${iconButton('close-modal','x','Close dialog')}</div><div class="sheet-body">${!o.project?`<div class="field"><label for="session-project">Session ownership</label><select class="input" id="session-project" name="project"><option value="">Global collection · no project</option>${D.projects.map(p=>`<option value="${esc(p.id)}">${esc(projectLabel(p.id))}</option>`).join('')}</select><div class="hint">This shared resource has no project owner. Attach a project only when that is the intended task.</div></div>`:''}<div class="field"><label>What kind of work?</label><div class="kind-options">${['Explore','Learn','Derive','Verify','Implement','Review','Write'].map((k,i)=>`<label><input type="radio" name="kind" value="${k.toLowerCase()}" ${i===0?'checked':''}>${k}</label>`).join('')}</div></div><div class="field"><label for="session-task">Task</label><textarea class="input" id="session-task" name="task" rows="3" required maxlength="1500">${esc(task)}</textarea><div class="hint">A task stays attached to this object while you work.</div></div>${selection?`<div class="selection-card"><div class="eyebrow">${icon('highlighter')}Precise selection</div><span class="pill active">${esc(selection.locator)}</span><blockquote>${esc(selection.text)}</blockquote><p class="inspect-path">${esc(selection.source)}</p></div>`:''}<div class="field"><label>Included context</label><div class="ctx-list"><div class="ctx-item">${icon(o.icon)}${esc(o.title)}<span class="why">origin</span></div><div class="ctx-item">${icon('file-text')}<span class="grow" style="overflow-wrap:anywhere">${esc(sourceFor(o))}</span><span class="why">source</span></div></div></div><div class="scope-row">${icon('shield-check')}Simulation · read-only fixtures · no model or tools run</div></div><div class="sheet-foot"><button class="btn ghost" type="button" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Open simulated session ${icon('arrow-right')}</button></div></form>`,'session');
  }
  function commands() {return [{label:'Toggle light / dark theme',kind:'Command',icon:'sun',action:'theme'},{label:'Split editor',kind:'Command',icon:'columns-2',action:'split'},{label:'Toggle activity panel',kind:'Command',icon:'panel-bottom',action:'panel'},{label:'Toggle sidebar',kind:'Command',icon:'panel-left',action:'sidebar'},...activityItems.filter(a=>a[0]!=='explorer').map(([a,g,l])=>({label:l,kind:'View',icon:g,value:uri(a)})),...D.projects.map(p=>({label:projectLabel(p.id),kind:'Project',icon:'folder-tree',value:uri('project',p.id)})),...D.threads.filter(t=>t.name).map(t=>({label:t.name,kind:'Thread',icon:'circle-dot',value:uri('thread',t.id)})),...D.knowledge.map(k=>({label:k.title,kind:'Knowledge',icon:'brain',value:uri('entry',k.id)})),{label:'An example paper',kind:'Paper',icon:'book-open',value:uri('paper',D.papers[0].id)},...Object.values(D.notes).map(n=>({label:n.title,kind:'Note',icon:'file-text',value:uri('note',n.id)})),...conversations.map(c=>({label:c.id==='c-trace'?'Reading discussion · Toy algebra':c.title,kind:'Conversation',icon:'messages-square',value:uri('conversation',c.id)}))];}
  let paletteResults=[];
  function renderPaletteResults() {paletteResults=commands().filter(x=>(x.label+' '+x.kind).toLowerCase().includes(state.paletteQuery.toLowerCase())).slice(0,16);state.paletteIndex=Math.max(0,Math.min(state.paletteIndex,paletteResults.length-1));$('#palette-results').innerHTML=paletteResults.length?`<div class="grp">${state.paletteQuery?'Matching resources & commands':'Commands & workspace'}</div>${paletteResults.map((r,i)=>`<button class="it ${i===state.paletteIndex?'on':''}" data-result="${i}" role="option" aria-selected="${i===state.paletteIndex}" id="palette-option-${i}">${icon(r.icon)}<span>${esc(r.label)}</span><span class="k">${esc(r.kind)}</span></button>`).join('')}`:empty('No matches','Try a project name, thread title, resource type or command.');$('#palette-search').setAttribute('aria-activedescendant',paletteResults.length?`palette-option-${state.paletteIndex}`:'');}
  function showPalette() {state.paletteQuery='';state.paletteIndex=0;showModal(`<div class="palette" role="dialog" aria-modal="true" aria-label="Find a resource or command"><div class="q">${icon('search')}<input id="palette-search" aria-label="Search resources and commands" role="combobox" aria-expanded="true" aria-controls="palette-results" autocomplete="off" placeholder="Find a resource or command…"><button class="kbd" data-action="close-modal">Esc</button></div><div class="res" id="palette-results" role="listbox"></div><div class="foot"><span>↑ ↓ navigate</span><span>↵ open</span><span>Esc close</span><span class="grow"></span><span>Local fixture index</span></div></div>`,'palette');renderPaletteResults();}
  function runResult(i) {const result=paletteResults[i];if(!result)return;closeModal();if(result.value)open(result.value);else action(result.action);}
  function toast(message) {document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),3500);}
  function action(name) {captureScrolls();if(name==='paper-prev'){state.paperPage=1;render();return;}if(name==='paper-next'){state.paperPage=2;render();return;}if(name==='back')return navigate(-1);if(name==='forward')return navigate(1);if(name==='palette')return showPalette();if(name==='split')return split();if(name==='unsplit')return unsplit();if(name==='close-modal')return closeModal();if(name==='theme')state.theme=state.theme==='light'?'dark':'light';if(name==='panel')state.panel=!state.panel;if(name==='sidebar')state.sidebar=!state.sidebar;if(name==='inspector')state.inspector=!state.inspector;render();}
  document.addEventListener('click',e=> {
    if(e.target.classList?.contains('scrim'))return closeModal();
    const b=e.target.closest('button');if(!b)return;
    const group=b.closest('[data-group]');if(group)state.focused=Number(group.dataset.group);
    if(b.dataset.open)return open(b.dataset.open);
    if(b.dataset.work)return startWork(b.dataset.work);
    if(b.dataset.selectPassage){const editor=b.closest('[data-group]'),passage=editor?.querySelector('#'+CSS.escape(b.dataset.selectPassage)),source=passage?.closest('.selectable-source');if(!source)return;return startWork(b.dataset.sourceObject,preciseSelection(source,passage.innerText,b.dataset.selectPassage));}
    if(b.dataset.selectionText){
      const selection=window.getSelection(),editor=b.closest('[data-group]');
      const sourceOf=node=>(node?.nodeType===Node.ELEMENT_NODE?node:node?.parentElement)?.closest('.selectable-source');
      const source=sourceOf(selection?.anchorNode),end=sourceOf(selection?.focusNode),expected=route(b.dataset.selectionText);
      if(!source||source!==end||source.closest('[data-group]')!==editor||source.dataset.sourceKind!==expected.kind||source.dataset.sourceId!==expected.id||!selection.toString().trim())return toast('Select text within this editor’s displayed resource first.');
      return startWork(b.dataset.selectionText,preciseSelection(source,selection.toString(),'selected text'));
    }

    if(b.dataset.action)return action(b.dataset.action);
    if(b.dataset.project){state.activity='explorer';state.project=b.dataset.project;state.projectSection='threads';return open(uri('project',b.dataset.project));}
    if(b.dataset.activity){state.activity=b.dataset.activity;state.sideQuery='';return open(state.activity==='explorer'?uri('project',state.project):uri(state.activity),{activity:false});}
    if(b.dataset.tab)return open(b.dataset.tab,{group:Number(b.dataset.tabGroup)});
    if(b.dataset.close)return closeTab(b.dataset.close,Number(b.dataset.tabGroup));
    if(b.dataset.projectSection){captureScrolls();state.projectSection=b.dataset.projectSection;return render();}
    if(b.dataset.codeSection){state.codeSection=b.dataset.codeSection;return render();}
    if(b.dataset.noteSection){state.noteSection=b.dataset.noteSection;return render();}
    if(b.dataset.theme){state.theme=b.dataset.theme;return render();}
    if(b.dataset.result!==undefined)return runResult(Number(b.dataset.result));
    if(b.dataset.review){state.reviewed.add(b.dataset.review);render();return toast('Marked reviewed in this preview only. No file changed.');}
    if(b.dataset.previewChange){const c=conversationBy(b.dataset.previewChange),ch=c.changes[0];return showModal(`<div class="sheet" role="dialog" aria-modal="true" aria-label="Synthetic change preview"><div class="sheet-head"><div class="grow"><div class="eyebrow">Simulated proposal · not applied</div><h2>Review in context.</h2></div>${iconButton('close-modal','x','Close proposal')}</div><div class="sheet-body"><p>${esc(ch.file)}</p><div class="notice">${icon('eye')}Synthetic numerical results below are fixture text, not validated results.</div>${codeBlock(ch.before.split('\n').map(l=>'- '+l).join('\n')+'\n'+ch.after.split('\n').map(l=>'+ '+l).join('\n'),true)}</div><div class="sheet-foot"><button class="btn" data-action="close-modal">Close preview</button></div></div>`,'change');}
  });
  document.addEventListener('input',e=>{if(e.target.id==='session-task')e.target.setCustomValidity('');if(e.target.id==='palette-search'){state.paletteQuery=e.target.value;state.paletteIndex=0;renderPaletteResults();}if(e.target.matches('.side-search')){state.sideQuery=e.target.value;const pos=e.target.selectionStart;$('.sidebar').innerHTML=renderSidebar();const input=$('.side-search');input.focus();input.setSelectionRange(pos,pos);}if(e.target.matches('.composer textarea'))state.drafts.set(e.target.closest('form').dataset.compose,e.target.value);});
  document.addEventListener('submit',e=> {
    if(e.target.id==='session-form'){e.preventDefault();const form=new FormData(e.target);const task=String(form.get('task')).trim();if(!task){$('#session-task').setCustomValidity('Enter a task to keep this session focused.');$('#session-task').reportValidity();return;}const origin=state.modalOrigin,o=object(origin),selection=state.modalSelection;const id=`local-${conversations.length+1}`;conversations.push({id,title:task.length>72?`${task.slice(0,69)}…`:task,task,kind:form.get('kind'),state:'ready',project:o.project||form.get('project')||null,origin:{type:o.kind,id:o.id,label:o.title},localOrigin:origin,local:true,selection,localMessages:[],context:[{label:o.title,ref:sourceFor(o),why:'origin'}],changes:selection?[{title:'Keep the verification boundary beside the selected definition',file:selection.kind==='note'?selection.source:'Session outcome · proposed reading note',before:selection.text,after:selection.text+'\n\nIndependent next check: assess the effect of grid refinement separately from the residual stopping criterion.'}]:[]});closeModal();if(state.groups.length===1)split();open(uri('conversation',id));toast('Simulated session created with its object context.');}
    if(e.target.dataset.compose){e.preventDefault();state.focused=Number(e.target.closest('[data-group]').dataset.group);const input=e.target.querySelector('textarea'),value=input.value.trim();if(!value)return;const c=conversationBy(e.target.dataset.compose);c.localMessages.push({role:'user',text:value},{role:'agent',text:'Your message is now part of this local preview. The original task and source context remain attached. No model response, computation or file change has occurred.'});state.drafts.delete(c.id);render();const group=$(`[data-group="${state.focused}"]`),body=$('.session-body',group);body.scrollTop=body.scrollHeight;$('.composer textarea',group).focus();}
  });
  document.addEventListener('keydown',e=> {
    const mod=e.ctrlKey||e.metaKey;
    if(e.key==='Escape'&&state.modal){e.preventDefault();return closeModal();}
    if(state.modal==='palette'&&['ArrowDown','ArrowUp','Enter'].includes(e.key)){e.preventDefault();if(e.key==='Enter')return runResult(state.paletteIndex);state.paletteIndex=(state.paletteIndex+(e.key==='ArrowDown'?1:-1)+paletteResults.length)%Math.max(1,paletteResults.length);renderPaletteResults();$(`#palette-option-${state.paletteIndex}`)?.scrollIntoView({block:'nearest'});return;}
    if(state.modal&&e.key==='Tab'){const nodes=[...$('#overlay').querySelectorAll('button,input,textarea,select,[tabindex="0"]')].filter(n=>!n.disabled);if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}return;}
    if(mod&&e.key.toLowerCase()==='k'){e.preventDefault();return state.modal?closeModal():showPalette();}
    if(state.modal)return;
    if(mod&&e.key==='Enter'&&e.target.closest('.composer')){e.preventDefault();return e.target.closest('form').requestSubmit();}
    if(mod&&e.key==='\\'){e.preventDefault();return split();}
    if(e.altKey&&e.key==='ArrowLeft'){e.preventDefault();return navigate(-1);}
    if(e.altKey&&e.key==='ArrowRight'){e.preventDefault();return navigate(1);}
    if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;
    if(mod&&e.key.toLowerCase()==='b'){e.preventDefault();return action('sidebar');}
    if(mod&&e.key.toLowerCase()==='j'){e.preventDefault();return action('panel');}
  });
  window.addEventListener('popstate',e=>{if(e.state?.aitp!==undefined&&state.history[e.state.aitp]){state.cursor=e.state.aitp;open(state.history[state.cursor],{history:false});}});
  history.replaceState({aitp:0},'',`#/${encodeURIComponent(initial)}`);
  inferActivity(initial);render();
})();
